export const meta = {
  "slug": "hugeicons-compass",
  "family": "hugeicons",
  "name": "compass",
  "category": "Navigation",
  "motion": "orbit",
  "component": "createHugeiconsCompassIcon"
};

export function createHugeiconsCompassIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
